VStack(alignment: .leading, spacing: theme.spacing.space4) {
    ForEach(Array(steps.enumerated()), id: \.element.id) { index, step in
        MonarchCard {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                HStack(alignment: .top, spacing: theme.spacing.space2) {
                    MonarchIcon(systemName: "circle.grid.2x3.fill", size: .sm)
                        .foregroundStyle(theme.colors.textMuted)
                        .padding(.top, theme.spacing.space1)
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text("Step \(index + 1), \(channel(step.channel).label)")
                            .monarchTextStyle(.bodyStrong)
                            .accessibilityAddTraits(.isHeader)
                        Text(when(step.waitMinutes)).monarchTextStyle(.caption)
                    }
                    Spacer(minLength: 0)
                    MonarchButton("Remove step \(index + 1)", systemImage: "xmark", variant: .ghost, size: .sm, isIconOnly: true) {
                        steps.remove(at: index)
                    }
                    MonarchButton("Move step \(index + 1) up", systemImage: "chevron.up", variant: .ghost, size: .sm, isIconOnly: true) {
                        steps.swapAt(index, index - 1)
                    }
                    .disabled(index == 0)
                    MonarchButton("Move step \(index + 1) down", systemImage: "chevron.down", variant: .ghost, size: .sm, isIconOnly: true) {
                        steps.swapAt(index, index + 1)
                    }
                    .disabled(index == steps.count - 1)
                }
                MonarchDurationInput("Wait before sending", minutes: $steps[index].waitMinutes, largestUnit: .days, helper: "For example 2d, 4h or 30m.", showsStepper: false)
                if channel(step.channel).hasSubject {
                    MonarchTextField("Subject", text: $steps[index].subject, isRequired: true)
                }
                MonarchTextField("Message", text: $steps[index].message, isRequired: true, axis: .vertical, lineLimit: 4...8)
                if let maxLength = channel(step.channel).maxLength {
                    Text(verbatim: "\(step.message.count) / \(maxLength)").monarchTextStyle(.caption)
                }
                MonarchFlowLayout(spacing: theme.spacing.space2) {
                    Text("Insert a variable").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    ForEach(variables, id: \.token) { variable in
                        MonarchButton(variable.label, variant: .secondary, size: .sm) {
                            steps[index].message += "{{\(variable.token)}}"
                        }
                    }
                }
                DisclosureGroup {
                    if channel(step.channel).hasSubject {
                        Text(render(step.subject)).monarchTextStyle(.bodyStrong)
                    }
                    Text(render(step.message)).monarchTextStyle(.body)
                } label: {
                    Text("Preview with sample data").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                }
                .padding(theme.spacing.space2)
                .background(RoundedRectangle(cornerRadius: MonarchTokens.Radius.md).fill(theme.colors.bgSubtle))
            }
        }
    }
    MonarchFlowLayout(spacing: theme.spacing.space2) {
        ForEach(channels, id: \.id) { option in
            MonarchButton("Add \(option.label) step", systemImage: "plus", variant: .secondary, size: .sm) {
                steps.append(Step(id: String(steps.count + 1), channel: option.id, waitMinutes: 1_440, subject: "", message: ""))
            }
        }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme

private struct Step: Identifiable {
    let id: String
    var channel: String
    var waitMinutes: Int?
    var subject: String
    var message: String
}

private let channels: [(id: String, label: String, hasSubject: Bool, maxLength: Int?)] = [
    (id: {{channels.0.value}}, label: {{channels.0.label}}, hasSubject: {{channels.0.hasSubject}}, maxLength: nil),
    (id: {{channels.1.value}}, label: {{channels.1.label}}, hasSubject: false, maxLength: {{channels.1.maxLength}}),
]
private let variables: [(token: String, label: String, sample: String)] = [
    (token: {{variables.0.token}}, label: {{variables.0.label}}, sample: {{variables.0.sample}}),
    (token: {{variables.1.token}}, label: {{variables.1.label}}, sample: {{variables.1.sample}}),
    (token: {{variables.2.token}}, label: {{variables.2.label}}, sample: {{variables.2.sample}}),
]
@State private var steps = [
    Step(id: "1", channel: {{steps.0.channel}}, waitMinutes: {{steps.0.delayMinutes}}, subject: {{steps.0.subject}}, message: {{steps.0.body}}),
    Step(id: "2", channel: {{steps.1.channel}}, waitMinutes: {{steps.1.delayMinutes}}, subject: "", message: {{steps.1.body}}),
]

private func channel(_ id: String) -> (id: String, label: String, hasSubject: Bool, maxLength: Int?) {
    channels.first { $0.id == id } ?? channels[0]
}

private func render(_ template: String) -> String {
    variables.reduce(template) { $0.replacingOccurrences(of: "{{\($1.token)}}", with: $1.sample) }
}

private func when(_ minutes: Int?) -> String {
    switch minutes ?? 0 {
    case 0: "Sent straight away"
    case let m where m % 1_440 == 0: "Sent \(m / 1_440)d after the previous step"
    case let m where m % 60 == 0: "Sent \(m / 60)h after the previous step"
    case let m: "Sent \(m)m after the previous step"
    }
}

